BEGIN;
CREATE OR REPLACE FUNCTION ledger.assert_balanced(p_tx uuid) RETURNS void LANGUAGE plpgsql AS $$ DECLARE d numeric; c numeric; n int; cur int; BEGIN SELECT count(*),count(DISTINCT currency),coalesce(sum(amount) FILTER(WHERE side='DEBIT'),0),coalesce(sum(amount) FILTER(WHERE side='CREDIT'),0) INTO n,cur,d,c FROM ledger.entries WHERE transaction_id=p_tx; IF n<2 THEN RAISE EXCEPTION 'ledger transaction % needs at least 2 entries',p_tx; END IF; IF cur<>1 THEN RAISE EXCEPTION 'ledger transaction % must use one currency',p_tx; END IF; IF d<>c THEN RAISE EXCEPTION 'ledger transaction % unbalanced: debit %, credit %',p_tx,d,c; END IF; END $$;
CREATE OR REPLACE FUNCTION ledger.guard_posting() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='POSTED' AND OLD.status<>'POSTED' THEN PERFORM ledger.assert_balanced(NEW.id); NEW.posted_at=coalesce(NEW.posted_at,now()); END IF; IF OLD.status='POSTED' AND NEW.status<>'POSTED' THEN RAISE EXCEPTION 'posted transaction is immutable; use reversal'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_ledger_post BEFORE UPDATE OF status ON ledger.transactions FOR EACH ROW EXECUTE FUNCTION ledger.guard_posting();
CREATE OR REPLACE FUNCTION ledger.block_posted_entry_change() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE s ledger.transaction_status; BEGIN SELECT status INTO s FROM ledger.transactions WHERE id=coalesce(OLD.transaction_id,NEW.transaction_id); IF s='POSTED' THEN RAISE EXCEPTION 'entries of posted transaction are immutable'; END IF; RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER trg_entries_update BEFORE UPDATE OR DELETE ON ledger.entries FOR EACH ROW EXECUTE FUNCTION ledger.block_posted_entry_change();
COMMIT;
